-- PostgreSQL funksiya/prosedur strukturu:
CREATE OR REPLACE FUNCTION core.fn_calc_discount(p_premium NUMERIC, p_claims INT)
RETURNS NUMERIC
LANGUAGE plpgsql
AS $$
DECLARE
    v_discount NUMERIC := 0;
BEGIN
    IF p_claims = 0 THEN
        v_discount := p_premium * 0.15; -- 15% endirim
    END IF;
    RETURN v_discount;
END;
$$;
